contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _to, uint256 _value) public {
        // Precondition: must be able to make a successful transfer.
        require(_to != address(0));
        require(!c.frozenAccount(_to));
        require(c.balanceOf(address(this)) >= _value);

        // Capture the exact condition under which the internal _transfer would
        // not revert for the test contract as the sender.
        require(c.balanceOf(_to) + _value >= c.balanceOf(_to));

        // The deciding call: must not revert.  If it does, the returned value
        // is irrelevant and the test would have failed the precondition above.
        // Because of the precondition, the call must succeed and return true.
        bool ret = c.transfer(_to, _value);

        // Post-condition: the returned value is exactly true for a successful transfer.
        assert(ret == true);
    }

    receive() external payable {}
}

